   {logs.length>0&&<div className="worklogStrip">{logs.slice(0,6).map(entry=><span key={entry.id}><b>{entry.worker}</b> {entry.ended_at?durText(entry.duration_minutes):'w trakcie'}</span>)}</div>}
   <div className="actionrow"><button onClick={()=>api.orders.exportPdf(o.id,'intake')}>PDF przyjęcia</button><button onClick={()=>api.orders.exportPdf(o.id,'order')}>PDF zlecenia</button><button onClick={()=>api.orders.exportPdf(o.id,'release')}>PDF wydania</button><button onClick={()=>api.knowledge.fromOrder(o.id)}>→ baza wiedzy</button></div>
