function FinanceModal({order,onClose,saved}){const[d,setD]=useState({...order});const fields=[['labor_hours','Godziny pracy'],['labor_rate','Stawka zł/h'],['parts_cost','Zakup części'],['parts_sale','Sprzedaż części'],['other_cost','Inne koszty'],['other_sale','Inna sprzedaż'],['diagnosis_fee','Diagnostyka'],['discount','Rabat']];return <Modal title="Finanse zlecenia" close={onClose}><div className="formgrid">{fields.map(([k,l])=><label key={k}>{l}<input type="number" step="0.1" value={d[k]||0} onChange={e=>setD({...d,[k]:e.target.value})}/></label>)}</div><button className="primary" onClick={async()=>{await api.orders.updateFinancials(order.id,d);saved()}}>Zapisz</button></Modal>}
