 return <div className="customerApprovalBack"><div className="customerApproval"><div className="customerBrand"><div className="customerLogo">A</div><div><b>AUTOLOGIKA</b><span>Diagnostyka • Mechanika • Elektronika • Programowanie</span></div><button onClick={close}>×</button></div><div className="customerVehicle"><span>KOSZTORYS NAPRAWY</span><h1>{order.make} {order.model}</h1><p>{order.plate} {order.vin?'· VIN '+order.vin:''}</p></div>{diag?.conclusion&&<div className="customerDiagnosis"><span>Wynik diagnostyki</span><p>{diag.conclusion}</p></div>}<div className="customerQuoteList">{quote.items.map(x=><div key={x.id}><div><b>{x.work_name||x.name}</b>{x.variant_name&&<small>{x.variant_name}</small>}<span>{x.kind==='ROBOCIZNA'?'Robocizna':x.kind==='CZESC'?'Część':'Materiał'}</span>{(x.customer_description||x.notes)&&<p>{x.customer_description||x.notes}</p>}</div><strong>{money(x.kind==='ROBOCIZNA'?x.labor_hours*x.labor_rate:x.qty*x.unit_price)}</strong></div>)}</div><div className="customerTotal"><span>ŁĄCZNA WARTOŚĆ</span><b>{money(quote.total)}</b></div>{photos.length>0&&<div className="customerEvidence"><span>Dokumentacja w zleceniu</span><b>{photos.length} plików / zdjęć</b></div>}<label className="customerNote">Uwagi klienta<textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="Opcjonalnie"/></label>{ap?.status==='PENDING'?<div className="customerDecision"><button className="customerDecline" disabled={busy} onClick={()=>decide('DECLINED')}>ODRZUCAM</button><button className="customerAccept" disabled={busy} onClick={()=>decide('APPROVED')}>✓ AKCEPTUJĘ {money(quote.total)}</button></div>:<div className={'customerResult '+(ap?.status||'').toLowerCase()}>{ap?.status==='APPROVED'?'✓ Kosztorys zaakceptowany':'× Kosztorys odrzucony'}</div>}<small className="customerLegal">Decyzja zostanie zapisana w historii zlecenia wraz z datą i godziną.</small></div></div>
