   <Panel title="Dokument sprzedaży — numer referencyjny"><p className="muted">To tylko ewidencja numeru dokumentu wystawionego w zewnętrznym systemie kasowym/fakturowym. Autologika OS nie wystawia tu dokumentu fiskalnego.</p><div className="formgrid"><label>Typ<select value={doc.document_type} onChange={e=>setDoc({...doc,document_type:e.target.value})}><option>PARAGON</option><option>FAKTURA</option><option>INNY</option></select></label><label>Numer<input value={doc.document_no} onChange={e=>setDoc({...doc,document_no:e.target.value})}/></label><label className="wide">Uwagi<input value={doc.note} onChange={e=>setDoc({...doc,note:e.target.value})}/></label></div><button className="primary" onClick={()=>api.salesRefs.add(order.id,doc).then(reload)}>Zapisz numer dokumentu</button>{refs.map(x=><div className="docRef" key={x.id}><b>{x.document_type} {x.document_no||'bez numeru'}</b><span>{new Date(x.issued_at).toLocaleString('pl-PL')}</span></div>)}</Panel>
